import java.io.*;
import java.util.*;

public class Main {
    public static void main(String[] args) {
        InputReader in = new InputReader(System.in);
        PrintWriter out = new PrintWriter(System.out);
        new TaskC().solve(new Context(in, out));
        out.close();
    }
}

class Context {
    InputReader in;
    PrintWriter out;
    Context(InputReader in, PrintWriter out) { this.in = in; this.out = out; }
}

class TaskC {
    private class State {
        int n, m, step, numFree, cur, res;
        int[][] f;
        int[] dx = new int[] {-1, 0, 1, 0, 0};
        int[] dy = new int[] {0, 1, 0, -1, 0};
    }

    private State st;

    public void solve(Context ctx) {
        int n = ctx.in.nextInt();
        int m = ctx.in.nextInt();
        if (n > m) {
            int t = m;
            m = n;
            n = t;
        }
        st = new State();
        st.n = n; st.m = m;
        st.f = new int[n][m];
        st.res = Integer.MAX_VALUE;
        st.cur = 0;
        st.step = 1;
        st.numFree = n * m;
        rec(0, 0);
        ctx.out.println(n * m - st.res);
    }

    private void rec(int x, int y) {
        if (st.numFree == 0) {
            st.res = Math.min(st.res, st.cur);
            return;
        }
        if (x >= st.n) return;
        if (y >= st.m) {
            rec(x + 1, 0);
            return;
        }
        if (st.f[x][y] != 0) {
            rec(x, y + 1);
            return;
        }

        put(x, y);
        rec(x, y + 1);
        remove(x, y);

        if (isValid(x + 1, y)) {
            put(x + 1, y);
            rec(x, y + 1);
            remove(x + 1, y);
        }

        if (isValid(x, y + 1)) {
            put(x, y + 1);
            rec(x, y + 1);
            remove(x, y + 1);
        }
    }

    private void put(int x, int y) {
        for (int i = 0; i < 5; ++i) {
            int nx = x + st.dx[i];
            int ny = y + st.dy[i];
            if (isValid(nx, ny)) {
                if (st.f[nx][ny] == 0) {
                    --st.numFree;
                    st.f[nx][ny] = st.step;
                }
            }
        }
        ++st.step;
        ++st.cur;
    }

    private void remove(int x, int y) {
        --st.step;
        for (int i = 0; i < 5; ++i) {
            int nx = x + st.dx[i];
            int ny = y + st.dy[i];
            if (isValid(nx, ny)) {
                if (st.f[nx][ny] == st.step) {
                    ++st.numFree;
                    st.f[nx][ny] = 0;
                }
            }
        }
        --st.cur;
    }

    private boolean isValid(int x, int y) {
        return x >= 0 && y >= 0 && x < st.n && y < st.m;
    }
}

class InputReader {
    private BufferedReader reader;
    private StringTokenizer stt;

    public InputReader(InputStream stream) {
        reader = new BufferedReader(new InputStreamReader(stream));
    }

    public String nextLine() {
        try {
            return reader.readLine().trim();
        } catch (IOException e) {
            return null;
        }
    }

    public String nextString() {
        while (stt == null || !stt.hasMoreTokens()) {
            stt = new StringTokenizer(nextLine());
        }
        return stt.nextToken();
    }

    public int nextInt() {
        return Integer.parseInt(nextString());
    }
}
